import type { CalendarImpactItem, ProjectRuntimeSettings, RuntimeSettingCategory, UserSession } from '@pacom/contracts';
import { E7F_IDS, type PacomDataAdapter } from '../../adapters';

const SETTING_CATEGORIES: Array<{ id: RuntimeSettingCategory; label: string }> = [
  { id: 'calendar', label: '运行日历' },
  { id: 'weather_area', label: '气象与面积' },
  { id: 'lighting', label: '照明策略' },
  { id: 'hvac', label: '暖通策略' },
  { id: 'metering_carbon', label: '计量与碳排' },
  { id: 'alarm_rules', label: '告警规则' },
  { id: 'templates', label: '参数模板' },
];

export async function mountSettingsView(
  root: HTMLElement,
  adapter: PacomDataAdapter,
  session: UserSession
): Promise<void> {
  let category: RuntimeSettingCategory = 'calendar';
  let data: ProjectRuntimeSettings = await adapter.getRuntimeSettings(E7F_IDS.projectId);
  let draftStart = data.calendar.workdayStart;
  let draftEnd = data.calendar.workdayEnd;
  let impacts: CalendarImpactItem[] = [];
  let notice = '';
  let errorMsg = '';

  function render(): void {
    const filteredRules = data.rules.filter((r) => r.category === category);
    root.innerHTML = `
      <div class="pacom-shell">
        <header class="pacom-header">
          <div class="pacom-header-top">
            <h1 class="pacom-title">运行设置</h1>
            <div class="pacom-header-meta">
              <span class="pacom-badge pacom-badge--neutral">项目范围：广实2号园</span>
              <span class="pacom-badge ${session.scope.canEditDeployment ? 'pacom-badge--online' : 'pacom-badge--warning'}">
                ${session.scope.canEditDeployment ? '可修改并下发配置' : '当前角色只读'}
              </span>
            </div>
          </div>
          <div class="pacom-header-toolbar">
            <div class="pacom-tabs" role="tablist">
              ${SETTING_CATEGORIES.map(
                (c) => `<button class="pacom-tab" role="tab" aria-selected="${category === c.id}" data-scat="${c.id}">${c.label}</button>`
              ).join('')}
            </div>
          </div>
        </header>

        ${notice ? `<div class="pacom-badge pacom-badge--online" style="height:auto; padding:8px 12px;">${notice}</div>` : ''}
        ${errorMsg ? `<div class="pacom-alert-banner">${errorMsg}</div>` : ''}

        <div class="pacom-content-page" style="padding:0;">
          ${
            category === 'calendar'
              ? `
              <section class="pacom-card">
                <h2 class="pacom-drawer-title">项目工作时间日历（版本 v${data.calendar.version}）</h2>
                <div style="display:flex; align-items:flex-end; gap:12px; flex-wrap:wrap;">
                  <label class="pacom-field">
                    <span>上班时间</span>
                    <input class="pacom-input" type="time" data-cal-start value="${draftStart}" />
                  </label>
                  <label class="pacom-field">
                    <span>下班时间</span>
                    <input class="pacom-input" type="time" data-cal-end value="${draftEnd}" />
                  </label>
                  <button class="pacom-btn" data-preview-impact="1">保存前预览受影响规则</button>
                  <button class="pacom-btn pacom-btn--primary" data-save-cal="1">保存并校验版本</button>
                </div>
                <div class="pacom-row-sub">夜间巡检窗口：${data.calendar.nightGuardStart} – ${data.calendar.nightGuardEnd}（若下班时间晚于 21:30 将自动提示交叠冲突）</div>

                ${
                  impacts.length > 0
                    ? `
                    <div style="margin-top:8px; display:flex; flex-direction:column; gap:6px;">
                      <strong style="font-size:13px;">受影响的定时与夜间规则预览（${impacts.length} 条）</strong>
                      ${impacts
                        .map(
                          (im) => `
                          <div class="pacom-receipt-item">
                            <div>
                              <strong>${im.ruleName}</strong>
                              <div class="pacom-row-sub">原窗口：${im.beforeWindow} → 新窗口：${im.afterWindow}</div>
                              ${im.conflictWarning ? `<div style="color:var(--pacom-status-critical);">${im.conflictWarning}</div>` : ''}
                            </div>
                            <span class="pacom-badge ${im.conflictWarning ? 'pacom-badge--critical' : 'pacom-badge--accent'}">${im.conflictWarning ? '交叠警告' : '自动跟随'}</span>
                          </div>`
                        )
                        .join('')}
                    </div>`
                    : ''
                }
              </section>`
              : `
              <section class="pacom-card">
                <h2 class="pacom-drawer-title">${SETTING_CATEGORIES.find((c) => c.id === category)?.label}（${filteredRules.length}）</h2>
                ${filteredRules
                  .map(
                    (r) => `
                    <div class="pacom-receipt-item">
                      <div>
                        <strong>${r.name}</strong> <span class="pacom-row-sub">v${r.version} · ${r.scopeLabel}</span>
                        <div class="pacom-row-sub">${r.summary} · 回执：${r.receiptSummary ?? '-'}</div>
                      </div>
                      <button class="pacom-btn ${r.enabled ? 'pacom-btn--primary' : ''}" data-toggle-rule="${r.id}" data-rule-ver="${r.version}" data-rule-next="${!r.enabled}">
                        ${r.enabled ? '已启用（点击停用）' : '已停用（点击启用）'}
                      </button>
                    </div>`
                  )
                  .join('')}
              </section>`
          }
        </div>
      </div>
    `;

    root.querySelectorAll<HTMLButtonElement>('[data-scat]').forEach((btn) => {
      btn.addEventListener('click', () => {
        category = btn.dataset.scat as RuntimeSettingCategory;
        notice = '';
        errorMsg = '';
        render();
      });
    });

    root.querySelector<HTMLInputElement>('[data-cal-start]')?.addEventListener('change', (e) => {
      draftStart = (e.currentTarget as HTMLInputElement).value;
    });
    root.querySelector<HTMLInputElement>('[data-cal-end]')?.addEventListener('change', (e) => {
      draftEnd = (e.currentTarget as HTMLInputElement).value;
    });

    root.querySelector<HTMLButtonElement>('[data-preview-impact]')?.addEventListener('click', async () => {
      errorMsg = '';
      impacts = await adapter.previewCalendarImpact(E7F_IDS.projectId, draftStart, draftEnd);
      render();
    });

    root.querySelector<HTMLButtonElement>('[data-save-cal]')?.addEventListener('click', async () => {
      errorMsg = '';
      try {
        const updated = await adapter.saveWorkCalendar(E7F_IDS.projectId, draftStart, draftEnd, data.calendar.version);
        data = { ...data, calendar: updated };
        notice = `运行日历已保存至 v${updated.version}（${updated.workdayStart} - ${updated.workdayEnd}）`;
        impacts = [];
        render();
      } catch (err) {
        errorMsg = err instanceof Error ? err.message : String(err);
        render();
      }
    });

    root.querySelectorAll<HTMLButtonElement>('[data-toggle-rule]').forEach((btn) => {
      btn.addEventListener('click', async () => {
        errorMsg = '';
        try {
          await adapter.toggleRuntimeRule(btn.dataset.toggleRule!, btn.dataset.ruleNext === 'true', Number(btn.dataset.ruleVer));
          data = await adapter.getRuntimeSettings(E7F_IDS.projectId);
          notice = '规则状态与版本回执已更新';
          render();
        } catch (err) {
          errorMsg = err instanceof Error ? err.message : String(err);
          render();
        }
      });
    });
  }

  render();
}
