import type { PlatformRole, UserSession } from '@pacom/contracts';
import { DEMO_ROLE_PROFILES, type PacomDataAdapter } from '../adapters';
import { mountAccountView } from '../features/account/account-view';
import { mountAlarmsView } from '../features/alarms/alarms-view';
import { mountAnalysisView } from '../features/analysis/analysis-view';
import { mountDeploymentView } from '../features/deployment/deployment-view';
import { mountE7FWorkspace } from '../features/e7f-slice/workspace';
import { mountScenesView } from '../features/scenes/scenes-view';
import { mountSettingsView } from '../features/settings/settings-view';

export type WorkspaceRoute =
  | 'home'
  | 'analysis'
  | 'alarms'
  | 'scenes'
  | 'settings'
  | 'deployment'
  | 'account';

interface NavItem {
  id: WorkspaceRoute;
  label: string;
  iconSvg: string;
}

const SIDEBAR_COLLAPSE_KEY = 'pacom.web.sidebar.collapsed';

const NAV_ITEMS: NavItem[] = [
  { id: 'home', label: '首页', iconSvg: '<path d="M3 10.5 12 3l9 7.5"/><path d="M5 9.5V20h14V9.5"/>' },
  { id: 'analysis', label: '数据分析', iconSvg: '<path d="M4 19h16"/><path d="M7 16v-5"/><path d="M12 16V7"/><path d="M17 16v-8"/>' },
  { id: 'alarms', label: '告警工单', iconSvg: '<path d="M12 4 3 19h18L12 4Z"/><path d="M12 10v4"/><path d="M12 17h.01"/>' },
  { id: 'scenes', label: '场景', iconSvg: '<circle cx="12" cy="12" r="4"/><path d="M12 2v3M12 19v3M4.9 4.9l2.1 2.1M17 17l2.1 2.1M2 12h3M19 12h3"/>' },
  { id: 'settings', label: '运行设置', iconSvg: '<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="2.5"/><circle cx="15" cy="17" r="2.5"/>' },
  { id: 'deployment', label: '系统部署', iconSvg: '<rect x="3" y="4" width="7" height="6" rx="1.5"/><rect x="14" y="4" width="7" height="6" rx="1.5"/><rect x="8.5" y="14" width="7" height="6" rx="1.5"/><path d="M6.5 10v2h11v-2M12 12v2"/>' },
  { id: 'account', label: '账户', iconSvg: '<circle cx="12" cy="8" r="3.5"/><path d="M5 20a7 7 0 0 1 14 0"/>' },
];

function parseRoute(): WorkspaceRoute {
  const hash = window.location.hash.replace(/^#\/?/, '').split('?')[0];
  if (NAV_ITEMS.some((n) => n.id === hash)) return hash as WorkspaceRoute;
  return 'home';
}

export async function mountAppShell(
  root: HTMLElement,
  adapter: PacomDataAdapter,
  initialSession: UserSession,
  onLoggedOut: () => void
): Promise<void> {
  let session = initialSession;
  let route: WorkspaceRoute = parseRoute();
  let collapsed = localStorage.getItem(SIDEBAR_COLLAPSE_KEY) === '1';
  let navSearch = '';

  async function renderStage(stage: HTMLElement): Promise<void> {
    switch (route) {
      case 'home':
        await mountE7FWorkspace(stage, adapter, session);
        return;
      case 'analysis':
        await mountAnalysisView(stage, adapter, session);
        return;
      case 'alarms':
        await mountAlarmsView(stage, adapter, session);
        return;
      case 'scenes':
        await mountScenesView(stage, adapter, session);
        return;
      case 'settings':
        await mountSettingsView(stage, adapter, session);
        return;
      case 'deployment':
        await mountDeploymentView(stage, adapter, session);
        return;
      case 'account':
        await mountAccountView(
          stage,
          adapter,
          session,
          (next) => {
            session = next;
            void render();
          },
          onLoggedOut
        );
        return;
    }
  }

  async function render(): Promise<void> {
    const filteredNav = navSearch.trim() ? NAV_ITEMS.filter((n) => n.label.includes(navSearch.trim())) : NAV_ITEMS;
    const isDemo = adapter.mode === 'demo' && typeof adapter.switchDemoRole === 'function';

    root.innerHTML = `
      <div class="pacom-app-frame">
        <aside class="pacom-nav-rail ${collapsed ? 'is-collapsed' : ''}" aria-label="主导航">
          <div class="pacom-nav-brand">
            <div class="pacom-nav-logo">
              <img src="/media/favicon.svg" alt="" width="22" height="22" />
              <span class="pacom-nav-logo-text">PACOM Station</span>
            </div>
            <button class="pacom-collapse-btn" data-role="toggle-sidebar" title="${collapsed ? '展开侧栏' : '收起侧栏'}" aria-label="${collapsed ? '展开侧栏' : '收起侧栏'}">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round">
                ${collapsed ? '<path d="m9 6 6 6-6 6"/>' : '<path d="m15 6-6 6 6 6"/>'}
              </svg>
            </button>
          </div>

          <div class="pacom-nav-search-wrap">
            <input class="pacom-nav-search" data-role="nav-search" placeholder="搜索工作区…" value="${navSearch}" />
          </div>

          <nav class="pacom-nav-list">
            ${filteredNav
              .map(
                (item) => `
                <button class="pacom-nav-item" data-route="${item.id}" aria-current="${route === item.id ? 'page' : 'false'}" title="${item.label}">
                  <svg class="pacom-nav-icon" viewBox="0 0 24 24">${item.iconSvg}</svg>
                  <span class="pacom-nav-label">${item.label}</span>
                </button>`
              )
              .join('')}
          </nav>

          <div class="pacom-nav-footer">
            <div class="pacom-nav-user-meta" style="font-size:12px;">
              <div style="font-weight:500;">${session.displayName}</div>
              <div style="color:var(--pacom-text-secondary);">${session.roleLabel} · ${adapter.mode.toUpperCase()}</div>
            </div>
            ${
              isDemo && !collapsed
                ? `
                <select class="pacom-nav-role-select" data-role="quick-role" aria-label="快捷切换演示角色">
                  ${(Object.keys(DEMO_ROLE_PROFILES) as PlatformRole[])
                    .map((r) => `<option value="${r}" ${r === session.role ? 'selected' : ''}>预览：${DEMO_ROLE_PROFILES[r].roleLabel}</option>`)
                    .join('')}
                </select>`
                : ''
            }
          </div>
        </aside>

        <div class="pacom-main-stage" data-role="main-stage"></div>
      </div>
    `;

    root.querySelector<HTMLButtonElement>('[data-role="toggle-sidebar"]')?.addEventListener('click', () => {
      collapsed = !collapsed;
      localStorage.setItem(SIDEBAR_COLLAPSE_KEY, collapsed ? '1' : '0');
      void render();
    });

    root.querySelector<HTMLInputElement>('[data-role="nav-search"]')?.addEventListener('input', (e) => {
      navSearch = (e.currentTarget as HTMLInputElement).value;
      void render();
    });

    root.querySelectorAll<HTMLButtonElement>('[data-route]').forEach((btn) => {
      btn.addEventListener('click', () => {
        route = btn.dataset.route as WorkspaceRoute;
        window.location.hash = `#${route}`;
        void render();
      });
    });

    root.querySelector<HTMLSelectElement>('[data-role="quick-role"]')?.addEventListener('change', async (e) => {
      if (!adapter.switchDemoRole) return;
      const role = (e.currentTarget as HTMLSelectElement).value as PlatformRole;
      session = await adapter.switchDemoRole(role);
      await render();
    });

    const stage = root.querySelector<HTMLElement>('[data-role="main-stage"]');
    if (stage) await renderStage(stage);
  }

  window.addEventListener('hashchange', () => {
    const next = parseRoute();
    if (next !== route) {
      route = next;
      void render();
    }
  });

  await render();
}
