import type { AlarmRecord, UserSession, WorkOrderRecord, WorkOrderStatus } from '@pacom/contracts';
import { E7F_IDS, type PacomDataAdapter } from '../../adapters';

export async function mountAlarmsView(
  root: HTMLElement,
  adapter: PacomDataAdapter,
  session: UserSession
): Promise<void> {
  let alarms: AlarmRecord[] = [];
  let workOrders: WorkOrderRecord[] = [];
  let statusFilter = 'all';
  let errorMsg = '';

  async function refresh(): Promise<void> {
    [alarms, workOrders] = await Promise.all([
      adapter.listAlarms(E7F_IDS.floorId),
      adapter.listWorkOrders(E7F_IDS.floorId),
    ]);
    render();
  }

  function render(): void {
    const visibleAlarms = statusFilter === 'all' ? alarms : alarms.filter((a) => a.status === statusFilter);
    root.innerHTML = `
      <div class="pacom-content-page">
        <div style="display:flex; justify-content:space-between; align-items:center;">
          <h1 class="pacom-title">告警工单</h1>
          <div style="display:flex; gap:8px; align-items:center;">
            <select class="pacom-select" data-alarm-filter>
              <option value="all" ${statusFilter === 'all' ? 'selected' : ''}>全部告警状态</option>
              <option value="active" ${statusFilter === 'active' ? 'selected' : ''}>待确认</option>
              <option value="acknowledged" ${statusFilter === 'acknowledged' ? 'selected' : ''}>已确认</option>
            </select>
            <span class="pacom-badge ${session.scope.canManageAlarms ? 'pacom-badge--online' : 'pacom-badge--warning'}">
              ${session.scope.canManageAlarms ? '可确认、转单与流转' : '只读权限'}
            </span>
          </div>
        </div>

        ${errorMsg ? `<div class="pacom-alert-banner">${errorMsg}</div>` : ''}

        <section class="pacom-card">
          <h2 class="pacom-drawer-title">E7F 实时告警队列（${visibleAlarms.length}）</h2>
          ${visibleAlarms
            .map(
              (a) => `
              <div class="pacom-receipt-item">
                <div>
                  <strong>${a.title}</strong> <span class="pacom-badge pacom-badge--neutral">${a.severity}</span>
                  <div class="pacom-row-sub">${a.message} · 设备：${a.deviceId}</div>
                </div>
                <div style="display:flex; gap:6px; align-items:center;">
                  ${a.status === 'active' ? `<button class="pacom-btn" data-ack="${a.id}">确认告警</button>` : `<span class="pacom-badge pacom-badge--online">已确认</span>`}
                  ${!a.workOrderId ? `<button class="pacom-btn pacom-btn--primary" data-to-wo="${a.id}">转工单</button>` : `<span class="pacom-badge pacom-badge--accent">已关联 ${a.workOrderId}</span>`}
                </div>
              </div>`
            )
            .join('')}
        </section>

        <section class="pacom-card">
          <h2 class="pacom-drawer-title">运维工单生命周期（${workOrders.length}）</h2>
          ${workOrders
            .map(
              (w) => `
              <div class="pacom-receipt-item">
                <div>
                  <strong>${w.title}</strong> <span class="pacom-row-sub">(${w.id})</span>
                  <div class="pacom-row-sub">${w.description}</div>
                </div>
                <select class="pacom-select" data-wo-status="${w.id}">
                  ${(['open', 'assigned', 'in_progress', 'resolved', 'closed'] as WorkOrderStatus[])
                    .map((st) => `<option value="${st}" ${w.status === st ? 'selected' : ''}>${st}</option>`)
                    .join('')}
                </select>
              </div>`
            )
            .join('')}
        </section>
      </div>
    `;

    root.querySelector<HTMLSelectElement>('[data-alarm-filter]')?.addEventListener('change', (e) => {
      statusFilter = (e.currentTarget as HTMLSelectElement).value;
      render();
    });

    root.querySelectorAll<HTMLButtonElement>('[data-ack]').forEach((btn) => {
      btn.addEventListener('click', async () => {
        errorMsg = '';
        try {
          await adapter.acknowledgeAlarm(btn.dataset.ack!, '告警工作区确认');
          await refresh();
        } catch (err) {
          errorMsg = err instanceof Error ? err.message : String(err);
          render();
        }
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-to-wo]').forEach((btn) => {
      btn.addEventListener('click', async () => {
        errorMsg = '';
        const alm = alarms.find((a) => a.id === btn.dataset.toWo);
        if (!alm) return;
        try {
          await adapter.createWorkOrder({
            floorId: alm.floorId,
            deviceId: alm.deviceId,
            alarmId: alm.id,
            title: `处置告警：${alm.title}`,
            description: alm.message,
          });
          await refresh();
        } catch (err) {
          errorMsg = err instanceof Error ? err.message : String(err);
          render();
        }
      });
    });

    root.querySelectorAll<HTMLSelectElement>('[data-wo-status]').forEach((sel) => {
      sel.addEventListener('change', async () => {
        errorMsg = '';
        try {
          await adapter.updateWorkOrderStatus(sel.dataset.woStatus!, sel.value as WorkOrderStatus);
          await refresh();
        } catch (err) {
          errorMsg = err instanceof Error ? err.message : String(err);
          await refresh();
        }
      });
    });
  }

  await refresh();
}
